const body = $input.item.json;
const audioUrl = body.audioUrl || body.audio_url || body.fileUrl || body.file_url;
const prompt = `You are an AI assistant for summarizing a sales call recording. Analyze the audio transcript and return a JSON object with these fields:
- category: what type of call this is (sales, support, onboarding, complaint, etc.)
- customer_request: what the customer asked for or wanted
- pain_points: the customer’s problems or complaints
- sales_rep_behavior: how the sales or support rep behaved
- key_takeaways: a short summary of the most important insights
- sentiment: overall sentiment (positive, neutral, negative)
If the audio content is not clearly a phone/business call, respond with category: unknown and brief explanation.
Transcript:
${body.transcript || ''}`;
return [{ json: { audioUrl, transcript: body.transcript || '', prompt } }];

const aiResponse = $input.item.json;
const output = aiResponse.output || aiResponse.choices?.[0]?.message || aiResponse.choices?.[0]?.text || aiResponse.data?.[0]?.text || aiResponse.choices?.[0]?.output?.[0]?.content?.[0]?.text || JSON.stringify(aiResponse);
return [{ json: { analysis: output, raw: aiResponse } }];
